PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "resultados_resultado" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha" date NOT NULL, "hora" time NOT NULL, "creado_en" datetime NOT NULL, "actualizado_en" datetime NOT NULL, "pick2" varchar(2) NULL, "pick3" varchar(3) NULL, "pick4" varchar(4) NULL, "pick5" varchar(5) NULL, "pf" varchar(2) NULL, "fijo" varchar(2) NULL, "corrido_1" varchar(2) NULL, "corrido_2" varchar(2) NULL, "centena_corrida_1" varchar(3) NULL, "centena_corrida_2" varchar(3) NULL, "parlet" varchar(200) NULL, "posicion" varchar(200) NULL, "tripleta" varchar(200) NULL, "vspf" varchar(200) NULL, "vspick2" varchar(200) NULL, "pick2vspf" varchar(200) NULL, "numero_ganador" varchar(10) NOT NULL, "derivados" text NOT NULL CHECK ((JSON_VALID("derivados") OR "derivados" IS NULL)), "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "creado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "sorteo_id" bigint NOT NULL REFERENCES "sorteos_sorteo" ("id") DEFERRABLE INITIALLY DEFERRED, "premios_generados" integer NOT NULL, "procesamiento_estado" varchar(20) NOT NULL, "procesamiento_fin" datetime NULL, "procesamiento_inicio" datetime NULL, "procesamiento_msg" varchar(255) NOT NULL);
COMMIT;
